const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};
const now = Date.now();
const items = Array.isArray($input.first().json.results) ? $input.first().json.results : [];
const stale = items
  .filter((item) => !item.completed_at)
  .map((item) => {
    const updatedAt = new Date(item.updated_at || 0).getTime();
    const ageDays = Math.floor((now - updatedAt) / (1000 * 60 * 60 * 24));
    return { id: item.id, title: item.name, priority: item.priority || 'none', ageDays };
  })
  .filter((item) => item.ageDays >= 3)
  .sort((left, right) => right.ageDays - left.ageDays);

const reportRelativePath = `stale-tasks/${new Date().toISOString().replace(/[:]/g, '-')}.md`;
const reportContent = [
  '# Plane Stale Task Detector',
  '',
  `Generated: ${new Date().toISOString()}`,
  `Stale tasks: ${stale.length}`,
  '',
  '## Tasks',
  '',
  ...(stale.length > 0 ? stale.map((item) => `- ${item.title} [priority=${item.priority}] stale for ${item.ageDays} days`) : ['No stale tasks detected.']),
].join('\n');

const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (!writeResponse.ok) throw new Error(`reports/write failed: ${writeResponse.status}`);

return [{ json: { staleCount: stale.length, stale, reportRelativePath } }];
